// Worker entry: wraps the OpenNext-generated worker (see wrangler.jsonc "main").
//
// Canonicalize to https before Next runs. Serving http:// with a 200 makes it a
// duplicate of the https canonical ("Alternative page with proper canonical tag"
// in Search Console). A Next middleware cannot do this under OpenNext: it rewrites
// a same-host redirect's Location back to the incoming scheme, which loops.
// Same block as merchants.london and rainmaker.org. localhost is exempt so
// `pnpm cf:preview` keeps working over http.
// @ts-ignore -- generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";
import { isSpamQuery } from "./lib/spam-query";

export default {
  async fetch(request: Request, env: unknown, ctx: unknown) {
    const url = new URL(request.url);
    if (url.protocol === "http:" && url.hostname !== "localhost" && url.hostname !== "127.0.0.1") {
      url.protocol = "https:";
      return Response.redirect(url.toString(), 301);
    }

    // Referrer-spam clones 301 to the clean URL, for the same reason the http
    // redirect above exists: served as-is each is a 200 duplicate with a
    // correct canonical, which Search Console files under a reason that can
    // never be validated away. Done here rather than in Next middleware
    // because, as above, OpenNext rewrites same-host redirect Locations.
    // /api is skipped; /opportunities and /tools/fair-value read their own
    // query parameters and do not match the signature. See lib/spam-query.ts.
    if (!url.pathname.startsWith("/api/") && isSpamQuery(url.searchParams)) {
      url.search = "";
      return Response.redirect(url.toString(), 301);
    }
    return handler.fetch(request, env, ctx);
  },
};

// @ts-ignore -- generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
